// PresenceStrip.jsx - Row of avatars showing who's here
function PresenceStrip({ users, currentUserId }) {
  if (!users || users.length === 0) return null;

  // Filter out current user, they know they're here
  const others = users.filter(u => u.id !== currentUserId);
  if (others.length === 0) return null;

  return (
    <div className="presence-strip">
      {others.map(user => (
        <div key={user.id} className="presence-avatar" title={user.username}>
          <img src={user.avatar} alt={user.username} />
        </div>
      ))}
    </div>
  );
}
```

