Perfect. Your combat engine in `lib/encounters.js` is already well-isolated. Here's how to make it work for both Arena and Quests:

---

## Unified Combat Design

### The Key Insight

Your combat engine (`lib/encounters.js`) is **location-agnostic**. It just needs:
- A `locationId` (where the fight happens)
- A `monsterId` (what to fight)
- Player joins/actions

The Arena is just one UI that calls `spawnEncounter()`. Quests can call the **same functions**.

---

### 1. Quest Combat Stage

A quest stage that triggers combat:

```json
"combat_bandits": {
  "type": "combat",
  "description": "Ambush on the road",
  "narration_prompt": "Three figures step out of the treeline, weapons drawn.",

  "monster": "bandit_leader",

  "victory": {
    "narration_prompt": "The bandits fall. The road is clear.",
    "next_stage": "loot_bodies",
    "sets_flag": "bandits_defeated"
  },

  "defeat": {
    "narration_prompt": "You collapse. When you wake, your gold pouch is gone.",
    "next_stage": "robbed",
    "sets_flag": "robbed_by_bandits"
  }
}
```

**No new combat code.** The quest just calls `spawnEncounter(questLocationId, "bandit_leader")` and waits for the outcome.

---

### 2. Quest Location Mapping

Quests run in a virtual "location" for combat purposes:

```javascript
// When quest enters a combat stage:
const combatLocationId = `quest_${questId}_${stageId}`;
const { encounter } = spawnEncounter(combatLocationId, stage.monster, questId);

// Store the encounter ID on the quest state
questState.activeEncounterId = encounter.id;
```

This way:
- Multiple quests can have combat simultaneously
- The same encounter engine handles everything
- No special combat code needed

---

### 3. Quest Combat Flow

```
┌─────────────────────────────────────────────────────┐
│  Quest Stage: type = "combat"                       │
│                                                     │
│  1. Quest Manager calls spawnEncounter()            │
│  2. WebSocket broadcasts encounter to quest location│
│  3. Quest UI shows EncounterBanner (same component) │
│  4. Players attack/defend/flee (same actions)       │
│  5. On victory/defeat → WS event fires              │
│  6. Quest Manager catches event, advances stage     │
└─────────────────────────────────────────────────────┘
```

---

### 4. Skill Check Actions

Add to the quest action schema:

```json
{
  "id": "persuade_merchant",
  "type": "skill_check",
  "label": "🗣️ Persuade the Merchant",

  "skill": "persuasion",
  "ability": "CHA",
  "dc": 14,

  "narration_prompt": "You try to haggle for a better price.",

  "success": {
    "narration_prompt": "The merchant sighs and lowers his price.",
    "sets_flag": "got_discount"
  },
  "failure": {
    "narration_prompt": "The merchant shakes his head. 'Price is firm.'",
    "advances": true,
    "next_stage": "pay_full_price"
  },
  "critical_success": {
    "narration_prompt": "The merchant laughs. 'I like you. Take it for half.'",
    "sets_flag": "huge_discount"
  },
  "critical_failure": {
    "narration_prompt": "You offend him deeply. He refuses to sell to you at all.",
    "advances": true,
    "next_stage": "kicked_out"
  }
}
```

---

### 5. Skill Check Server Endpoint

New route: `POST /api/quests/:questId/skill-check`

```javascript
// server/routes/quests.js (add to questmaster routes)

router.post('/:questId/skill-check', authRequired, async (req, res) => {
  const { questId } = req.params;
  const { actionId, roll } = req.body; // roll = d20 result from 3D dice

  const quest = loadQuest(questId);
  const action = getAction(quest, actionId);
  if (action.type !== 'skill_check') {
    return res.status(400).json({ error: 'Not a skill check action' });
  }

  // Get player's ability modifier from character sheet
  const sheet = getCharacterSheet(req.user.id);
  const abilityMod = getAbilityMod(sheet, action.ability); // CHA → +2, etc.
  const profBonus = sheet?.profBonus || 2;

  // Check if player is proficient in this skill
  const isProficient = sheet?.skills?.[action.skill]?.proficient || false;
  const totalBonus = abilityMod + (isProficient ? profBonus : 0);

  const total = roll + totalBonus;
  const dc = action.dc;

  // Determine outcome
  let outcome;
  if (roll === 20) outcome = 'critical_success';
  else if (roll === 1) outcome = 'critical_failure';
  else if (total >= dc) outcome = 'success';
  else outcome = 'failure';

  // Get the outcome definition
  const result = action[outcome] || action.failure;

  // Apply flags, advance stage if needed
  if (result.sets_flag) setQuestFlag(quest, result.sets_flag);
  if (result.advances) advanceStage(quest, result.next_stage);

  // Return result for narration
  res.json({
    roll,
    totalBonus,
    total,
    dc,
    outcome,
    narration: result.narration_prompt,
    advances: result.advances,
    nextStage: result.next_stage,
  });
});
```

---

### 6. Client Integration

The Quest UI detects action type and shows appropriate UI:

```jsx
// In QuestActionBar or similar

function handleAction(action) {
  if (action.type === 'skill_check') {
    // Show skill check modal with dice roll
    setSkillCheckModal({
      skill: action.skill,
      ability: action.ability,
      dc: action.dc,
      actionId: action.id,
    });
  } else if (action.type === 'combat') {
    // Spawn encounter at quest location
    spawnCombat(action.monster);
  } else {
    // Normal action
    submitAction(action.id);
  }
}
```

---

### 7. File Changes Summary

| File | Change |
|------|--------|
| `lib/encounters.js` | No changes (already generic) |
| `routes/quests.js` | Add `/skill-check` endpoint |
| `questmaster/bot.js` | When stage.type === 'combat', spawn encounter |
| `client/components/QuestPanel.jsx` | Detect combat stages, show EncounterBanner |
| `client/components/SkillCheckModal.jsx` | New: dice roll UI for skill checks |

---

### 8. Combat Stage Detection (Quest Manager)

```javascript
// In questmaster/bot.js or wherever stage advancement happens

async function enterStage(quest, stageId) {
  const stage = quest.stages[stageId];

  if (stage.type === 'combat') {
    // Spawn encounter using the shared combat engine
    const combatLocationId = `quest_${quest.id}`;
    const result = await api.post('/api/encounters/spawn', {
      locationId: combatLocationId,
      monsterId: stage.monster,
    });

    quest.activeEncounterId = result.encounter.id;
    quest.combatVictoryStage = stage.victory?.next_stage;
    quest.combatDefeatStage = stage.defeat?.next_stage;

    // The encounter system handles the rest
    // Quest listens for encounter_end WS event to advance
  }
}
```

---

### 9. Listening for Combat Outcome

```javascript
// WebSocket handler in quest context

ws.on('message', (data) => {
  const event = JSON.parse(data);

  if (event.type === 'encounter_end' && quest.activeEncounterId === event.encounterId) {
    if (event.outcome === 'victory') {
      advanceStage(quest.combatVictoryStage);
      narrate(quest.stages[currentStage].victory.narration_prompt);
    } else {
      advanceStage(quest.combatDefeatStage);
      narrate(quest.stages[currentStage].defeat.narration_prompt);
    }
    quest.activeEncounterId = null;
  }
});
```

---

**Bottom line:** Your combat engine is already reusable. You just need:

1. A way for quests to call `spawnEncounter()` with a quest-specific locationId
2. A skill check endpoint that uses character sheet stats
3. Client components that detect `type: "combat"` or `type: "skill_check"` and render the right UI

