### 2. Phaser Scene Structure

```javascript
// FishingScene.js - Key pieces

create() {
  // Parallax background layers
  this.sky = this.add.image(0, 0, 'sky').setOrigin(0, 0);
  this.farTrees = this.add.tileSprite(0, 200, width, 100, 'far_trees');

  // Animated water surface
  this.waterSurface = this.add.tileSprite(0, waterLineY, width, 80, 'water_tile');

  // Dock foreground
  this.dock = this.add.image(width/2, height - 50, 'dock');

  // Fishing rod (bottom of screen, angled)
  this.rod = this.add.sprite(width - 80, height - 20, 'rod');
  this.rod.setOrigin(0.5, 1); // pivot at handle

  // Bobber
  this.bobber = this.add.sprite(0, 0, 'bobber');
  this.bobber.setVisible(false);

  // Fishing line (graphics, drawn each frame)
  this.line = this.add.graphics();

  // Fish shadow (swims under water)
  this.fishShadow = this.add.sprite(0, 0, 'fish_shadow');
  this.fishShadow.setAlpha(0.4);
  this.fishShadow.setVisible(false);

  // Particle emitters
  this.splashEmitter = this.add.particles(0, 0, 'splash_drop', {...});
  this.rippleEmitter = this.add.particles(0, 0, 'ripple', {...});
}

update() {
  // Animate water scrolling
  this.waterSurface.tilePositionX += 0.5;

  // Draw curved line from rod tip to bobber
  if (this.bobber.visible) {
    this.drawFishingLine();
  }

  // Bobber bobbing on water
  if (this.state === 'waiting') {
    this.bobber.y = this.waterLineY + Math.sin(this.time.now / 500) * 3;
  }
}

drawFishingLine() {
  const rodTip = { x: this.rod.x + 60, y: this.rod.y - 180 };
  const bobberPos = { x: this.bobber.x, y: this.bobber.y };

  this.line.clear();
  this.line.lineStyle(2, 0xcccccc);

  // Bezier curve for natural droop
  const cp1 = { x: rodTip.x, y: rodTip.y + 50 };
  const cp2 = { x: bobberPos.x, y: bobberPos.y - 30 };

  this.line.beginPath();
  this.line.moveTo(rodTip.x, rodTip.y);
  // Phaser doesn't have bezierCurveTo, so approximate with segments
  this.drawCurve(rodTip, cp1, cp2, bobberPos);
  this.line.strokePath();
}
```

---

