## Touch Interaction

```js
// Raycaster to detect taps on liquid surface
const raycaster = new Raycaster();

function onPointerDown(event) {
  // Convert screen coords to normalized device coords
  const mouse = new Vector2(
    (event.clientX / window.innerWidth) * 2 - 1,
    -(event.clientY / window.innerHeight) * 2 + 1
  );

  raycaster.setFromCamera(mouse, camera);
  const hits = raycaster.intersectObject(liquidMesh);

  if (hits.length > 0) {
    const uv = hits[0].uv;
    liquidSurface.addRipple(uv.x, uv.y, 0.5);
    // Play little *bloop* sound
  }
}

// Also works for touch events on mobile
element.addEventListener('pointerdown', onPointerDown);
```

